"""Exception hierarchy for microdb."""

from __future__ import annotations


class MicroDBError(Exception):
    """Base class for every error raised by microdb."""


class LexError(MicroDBError):
    """Raised when the lexer meets a character it cannot tokenize."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset: int = offset


class ParseError(MicroDBError):
    """Raised when the token stream does not match the grammar."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset: int = offset


class SchemaError(MicroDBError):
    """Raised for invalid table definitions or unknown column lookups."""


class TypeMismatchError(MicroDBError):
    """Raised when operand types are not compatible with an operation."""


class UnknownColumnError(MicroDBError):
    """Raised when a column reference cannot be resolved."""


class AmbiguousColumnError(MicroDBError):
    """Raised when an unqualified column exists in more than one table."""


class UnknownTableError(MicroDBError):
    """Raised when a table name is not known."""


class UnknownFunctionError(MicroDBError):
    """Raised when a function name is not known."""


class ArityError(MicroDBError):
    """Raised when a function is called with the wrong number of arguments."""


class AggregateError(MicroDBError):
    """Raised when an aggregate is used where it is not allowed."""


class GroupingError(MicroDBError):
    """Raised when a projection is not compatible with GROUP BY."""

"""Value model: type inspection, three-valued logic, comparison and arithmetic.

There are exactly five value kinds.  NULL is represented by ``None`` and is not a
type of its own: it may appear in a column of any type.  ``bool`` is deliberately
treated as a distinct type even though Python considers it a subclass of ``int``.
"""

from __future__ import annotations

from .errors import TypeMismatchError

INT: str = "INT"
FLOAT: str = "FLOAT"
TEXT: str = "TEXT"
BOOL: str = "BOOL"
NULL: str = "NULL"

TYPE_NAMES: frozenset[str] = frozenset({INT, FLOAT, TEXT, BOOL})


def type_of(v: object) -> str:
    """Return the type name of ``v``, or ``"NULL"`` when ``v`` is ``None``."""
    if v is None:
        return NULL
    if isinstance(v, bool):
        return BOOL
    if isinstance(v, int):
        return INT
    if isinstance(v, float):
        return FLOAT
    if isinstance(v, str):
        return TEXT
    raise TypeMismatchError(f"unsupported value of Python type {type(v).__name__!r}")


def is_numeric(v: object) -> bool:
    """Return True for ``int`` and ``float`` values, excluding ``bool`` and ``None``."""
    if isinstance(v, bool) or v is None:
        return False
    return isinstance(v, (int, float))


def is_bool(v: object) -> bool:
    """Return True when ``v`` is a genuine boolean value."""
    return isinstance(v, bool)


def is_text(v: object) -> bool:
    """Return True when ``v`` is a text value."""
    return isinstance(v, str)


# --------------------------------------------------------------------------
# Three-valued logic.  ``None`` stands for UNKNOWN.
# --------------------------------------------------------------------------


def and_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued AND: FALSE dominates, so ``FALSE AND UNKNOWN`` is FALSE."""
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued OR: TRUE dominates, so ``TRUE OR UNKNOWN`` is TRUE."""
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not_(a: bool | None) -> bool | None:
    """Three-valued NOT: ``NOT UNKNOWN`` stays UNKNOWN."""
    if a is None:
        return None
    return not a


# --------------------------------------------------------------------------
# Comparison
# --------------------------------------------------------------------------


def _check_comparable(a: object, b: object) -> None:
    """Raise TypeMismatchError unless ``a`` and ``b`` are in the same comparison class."""
    if is_numeric(a) and is_numeric(b):
        return
    if is_bool(a) and is_bool(b):
        return
    if is_text(a) and is_text(b):
        return
    raise TypeMismatchError(
        f"cannot compare {type_of(a)} with {type_of(b)}"
    )


def compare_eq(a: object, b: object) -> bool | None:
    """SQL ``=``: UNKNOWN when either side is NULL, even for ``NULL = NULL``."""
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return a == b


def compare_lt(a: object, b: object) -> bool | None:
    """SQL ``<``: UNKNOWN when either side is NULL."""
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return a < b


def compare_op(op: str, a: object, b: object) -> bool | None:
    """Evaluate one of ``= <> < <= > >=`` with three-valued semantics."""
    if op == "=":
        return compare_eq(a, b)
    if op == "<>":
        return not_(compare_eq(a, b))
    if op == "<":
        return compare_lt(a, b)
    if op == ">":
        return compare_lt(b, a)
    if op == "<=":
        return or_(compare_lt(a, b), compare_eq(a, b))
    if op == ">=":
        return or_(compare_lt(b, a), compare_eq(a, b))
    raise TypeMismatchError(f"unknown comparison operator {op!r}")


def order_lt(a: object, b: object) -> bool:
    """Strict ordering between two non-NULL values, used by sorting and MIN/MAX."""
    result = compare_lt(a, b)
    return bool(result)


# --------------------------------------------------------------------------
# Arithmetic
# --------------------------------------------------------------------------


def _require_numeric(op: str, *values: object) -> None:
    for v in values:
        if not is_numeric(v):
            raise TypeMismatchError(
                f"operator {op!r} requires numeric operands, got {type_of(v)}"
            )


def arith(op: str, a: object, b: object) -> object:
    """Binary arithmetic with NULL propagation and NULL on division by zero."""
    if a is None or b is None:
        return None
    _require_numeric(op, a, b)
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        if b == 0:
            return None
        return float(a) / float(b)
    if op == "%":
        if type_of(a) != INT or type_of(b) != INT:
            raise TypeMismatchError("operator '%' requires two INT operands")
        if b == 0:
            return None
        return a % b
    raise TypeMismatchError(f"unknown arithmetic operator {op!r}")


def negate(a: object) -> object:
    """Unary minus: NULL propagates and the numeric type is preserved."""
    if a is None:
        return None
    _require_numeric("-", a)
    return -a

"""Schema layer: column definitions and in-memory tables."""

from __future__ import annotations

import dataclasses

from .errors import SchemaError
from .value import TYPE_NAMES, type_of


@dataclasses.dataclass(frozen=True)
class Column:
    """A named, typed column."""

    name: str
    type: str


def _coerce_cell(value: object, column: Column, row_index: int) -> object:
    """Validate one cell against its column type, widening INT to FLOAT if needed."""
    if value is None:
        return None
    actual = type_of(value)
    if actual == column.type:
        return value
    if column.type == "FLOAT" and actual == "INT":
        # The single implicit conversion in microdb: an INT stored in a FLOAT column.
        return float(value)
    raise SchemaError(
        f"row {row_index}: column {column.name!r} expects {column.type}, got {actual}"
    )


class Table:
    """An immutable-by-convention in-memory relation."""

    def __init__(self, name: str, columns: list[Column], rows: list[list[object]]) -> None:
        if not columns:
            raise SchemaError(f"table {name!r} must have at least one column")
        seen: set[str] = set()
        for column in columns:
            if column.name in seen:
                raise SchemaError(f"duplicate column name {column.name!r} in table {name!r}")
            seen.add(column.name)
            if column.type not in TYPE_NAMES:
                raise SchemaError(
                    f"column {column.name!r} has unknown type {column.type!r}"
                )
        self._name: str = name
        self._columns: list[Column] = list(columns)
        self._rows: list[list[object]] = [
            self._validate_row(row, index) for index, row in enumerate(rows)
        ]

    def _validate_row(self, row: list[object], index: int) -> list[object]:
        if len(row) != len(self._columns):
            raise SchemaError(
                f"row {index} has {len(row)} values but table {self._name!r} "
                f"has {len(self._columns)} columns"
            )
        return [
            _coerce_cell(value, column, index)
            for value, column in zip(row, self._columns)
        ]

    @property
    def name(self) -> str:
        """The table name."""
        return self._name

    @property
    def columns(self) -> list[Column]:
        """The column definitions."""
        return self._columns

    @property
    def rows(self) -> list[list[object]]:
        """The stored rows."""
        return self._rows

    def column_index(self, name: str) -> int:
        """Return the zero-based index of ``name``, raising SchemaError if unknown."""
        for index, column in enumerate(self._columns):
            if column.name == name:
                return index
        raise SchemaError(f"table {self._name!r} has no column {name!r}")

    def __repr__(self) -> str:
        return f"Table({self._name!r}, {len(self._columns)} columns, {len(self._rows)} rows)"

"""Lexer for the microdb query language."""

from __future__ import annotations

import dataclasses

from .errors import LexError

KEYWORDS: frozenset[str] = frozenset(
    {
        "SELECT", "DISTINCT", "FROM", "INNER", "LEFT", "JOIN", "ON", "WHERE",
        "GROUP", "BY", "HAVING", "ORDER", "ASC", "DESC", "LIMIT", "OFFSET",
        "AS", "AND", "OR", "NOT", "IS", "NULL", "TRUE", "FALSE",
    }
)

TWO_CHAR_OPERATORS: tuple[str, ...] = ("<>", "<=", ">=")
ONE_CHAR_OPERATORS: str = "=<>+-*/%(),."

INT_TOKEN: str = "INT"
FLOAT_TOKEN: str = "FLOAT"
TEXT_TOKEN: str = "TEXT"
IDENT_TOKEN: str = "IDENT"
KEYWORD_TOKEN: str = "KEYWORD"
OP_TOKEN: str = "OP"
EOF_TOKEN: str = "EOF"


@dataclasses.dataclass(frozen=True)
class Token:
    """A lexical token with its zero-based source offset."""

    kind: str
    value: object
    offset: int
    text: str


def _is_ident_start(ch: str) -> bool:
    return ch.isascii() and (ch.isalpha() or ch == "_")


def _is_ident_part(ch: str) -> bool:
    return ch.isascii() and (ch.isalnum() or ch == "_")


def _skip_ignorable(src: str, i: int) -> int:
    """Advance past whitespace and ``--`` comments, returning the new index."""
    n = len(src)
    while i < n:
        if src[i].isspace():
            i += 1
        elif src.startswith("--", i):
            while i < n and src[i] != "\n":
                i += 1
        else:
            break
    return i


def _lex_text(src: str, start: int) -> tuple[Token, int]:
    """Lex a single-quoted text literal; ``''`` denotes an embedded quote."""
    i = start + 1
    chars: list[str] = []
    n = len(src)
    while i < n:
        if src[i] == "'":
            if i + 1 < n and src[i + 1] == "'":
                chars.append("'")
                i += 2
                continue
            return Token(TEXT_TOKEN, "".join(chars), start, src[start : i + 1]), i + 1
        chars.append(src[i])
        i += 1
    raise LexError("unterminated text literal", start)


def _scan_digits(src: str, i: int) -> int:
    while i < len(src) and src[i].isdigit():
        i += 1
    return i


def _lex_number(src: str, start: int) -> tuple[Token, int]:
    """Lex an integer or float literal, including forms like ``1.`` and ``.5e-2``."""
    n = len(src)
    i = _scan_digits(src, start)
    is_float = False
    if i < n and src[i] == ".":
        is_float = True
        i = _scan_digits(src, i + 1)
    if i < n and src[i] in "eE":
        j = i + 1
        if j < n and src[j] in "+-":
            j += 1
        if j < n and src[j].isdigit():
            is_float = True
            i = _scan_digits(src, j)
    text = src[start:i]
    if is_float:
        return Token(FLOAT_TOKEN, float(text), start, text), i
    return Token(INT_TOKEN, int(text), start, text), i


def _lex_word(src: str, start: int) -> tuple[Token, int]:
    i = start
    while i < len(src) and _is_ident_part(src[i]):
        i += 1
    text = src[start:i]
    upper = text.upper()
    if upper in KEYWORDS:
        return Token(KEYWORD_TOKEN, upper, start, text), i
    return Token(IDENT_TOKEN, text, start, text), i


def _lex_operator(src: str, start: int) -> tuple[Token, int]:
    for candidate in TWO_CHAR_OPERATORS:
        if src.startswith(candidate, start):
            return Token(OP_TOKEN, candidate, start, candidate), start + 2
    ch = src[start]
    if ch in ONE_CHAR_OPERATORS:
        return Token(OP_TOKEN, ch, start, ch), start + 1
    raise LexError(f"unexpected character {ch!r}", start)


def tokenize(src: str) -> list[Token]:
    """Split ``src`` into tokens, ending with a single EOF token."""
    tokens: list[Token] = []
    i = 0
    n = len(src)
    while True:
        i = _skip_ignorable(src, i)
        if i >= n:
            break
        ch = src[i]
        if ch == "'":
            token, i = _lex_text(src, i)
        elif ch.isdigit() or (ch == "." and i + 1 < n and src[i + 1].isdigit()):
            token, i = _lex_number(src, i)
        elif _is_ident_start(ch):
            token, i = _lex_word(src, i)
        else:
            token, i = _lex_operator(src, i)
        tokens.append(token)
    tokens.append(Token(EOF_TOKEN, None, n, ""))
    return tokens

"""Parser: turns a token stream into a :class:`Query` tree."""

from __future__ import annotations

import dataclasses

from .errors import ParseError
from .lexer import (
    EOF_TOKEN,
    FLOAT_TOKEN,
    IDENT_TOKEN,
    INT_TOKEN,
    KEYWORD_TOKEN,
    OP_TOKEN,
    TEXT_TOKEN,
    Token,
    tokenize,
)

AGGREGATE_NAMES: frozenset[str] = frozenset({"count", "sum", "avg", "min", "max"})
COMPARISON_OPS: frozenset[str] = frozenset({"=", "<>", "<", "<=", ">", ">="})


@dataclasses.dataclass(frozen=True)
class Expr:
    """Base class for expression nodes; ``text`` is the collapsed source text."""

    text: str
    offset: int


@dataclasses.dataclass(frozen=True)
class Literal(Expr):
    value: object


@dataclasses.dataclass(frozen=True)
class ColumnRef(Expr):
    table: str | None
    name: str


@dataclasses.dataclass(frozen=True)
class Star(Expr):
    table: str | None


@dataclasses.dataclass(frozen=True)
class FuncCall(Expr):
    name: str
    args: tuple[Expr, ...]


@dataclasses.dataclass(frozen=True)
class Unary(Expr):
    op: str
    operand: Expr


@dataclasses.dataclass(frozen=True)
class Binary(Expr):
    op: str
    left: Expr
    right: Expr


@dataclasses.dataclass(frozen=True)
class Compare(Expr):
    op: str
    left: Expr
    right: Expr


@dataclasses.dataclass(frozen=True)
class IsNull(Expr):
    operand: Expr
    negated: bool


@dataclasses.dataclass(frozen=True)
class Not(Expr):
    operand: Expr


@dataclasses.dataclass(frozen=True)
class Logical(Expr):
    op: str
    left: Expr
    right: Expr


@dataclasses.dataclass(frozen=True)
class SelectItem:
    expr: Expr
    alias: str | None


@dataclasses.dataclass(frozen=True)
class JoinClause:
    kind: str
    table: str
    on: Expr


@dataclasses.dataclass(frozen=True)
class OrderItem:
    expr: Expr
    descending: bool


@dataclasses.dataclass(frozen=True)
class Query:
    """A parsed query, one field per clause."""

    select: tuple[SelectItem, ...]
    distinct: bool
    from_table: str
    join: JoinClause | None
    where: Expr | None
    group_by: tuple[Expr, ...]
    having: Expr | None
    order_by: tuple[OrderItem, ...]
    limit: int | None
    offset: int | None


def collapse(text: str) -> str:
    """Collapse every run of whitespace in ``text`` to a single space."""
    return " ".join(text.split())


def contains_aggregate(expr: Expr) -> bool:
    """Return True when ``expr`` contains an aggregate function call."""
    return any(isinstance(node, FuncCall) and node.name.lower() in AGGREGATE_NAMES
               for node in walk(expr))


def walk(expr: Expr) -> list[Expr]:
    """Return ``expr`` and all of its descendants in pre-order."""
    found: list[Expr] = [expr]
    for child in children(expr):
        found.extend(walk(child))
    return found


def children(expr: Expr) -> list[Expr]:
    """Return the direct sub-expressions of ``expr``."""
    if isinstance(expr, FuncCall):
        return list(expr.args)
    if isinstance(expr, (Binary, Compare, Logical)):
        return [expr.left, expr.right]
    if isinstance(expr, Unary):
        return [expr.operand]
    if isinstance(expr, Not):
        return [expr.operand]
    if isinstance(expr, IsNull):
        return [expr.operand]
    return []


class _Parser:
    """Recursive descent parser over a token list."""

    def __init__(self, src: str) -> None:
        self.src: str = src
        self.tokens: list[Token] = tokenize(src)
        self.pos: int = 0

    # -- token helpers ----------------------------------------------------

    def peek(self, ahead: int = 0) -> Token:
        index = min(self.pos + ahead, len(self.tokens) - 1)
        return self.tokens[index]

    def next(self) -> Token:
        token = self.tokens[self.pos]
        if token.kind != EOF_TOKEN:
            self.pos += 1
        return token

    def at_keyword(self, *names: str) -> bool:
        token = self.peek()
        return token.kind == KEYWORD_TOKEN and token.value in names

    def at_op(self, *ops: str) -> bool:
        token = self.peek()
        return token.kind == OP_TOKEN and token.value in ops

    def accept_keyword(self, *names: str) -> Token | None:
        if self.at_keyword(*names):
            return self.next()
        return None

    def accept_op(self, *ops: str) -> Token | None:
        if self.at_op(*ops):
            return self.next()
        return None

    def expect_keyword(self, name: str) -> Token:
        if not self.at_keyword(name):
            raise self.error(f"expected {name}")
        return self.next()

    def expect_op(self, op: str) -> Token:
        if not self.at_op(op):
            raise self.error(f"expected {op!r}")
        return self.next()

    def expect_ident(self) -> Token:
        token = self.peek()
        if token.kind != IDENT_TOKEN:
            raise self.error("expected an identifier")
        return self.next()

    def error(self, message: str) -> ParseError:
        token = self.peek()
        found = token.text if token.kind != EOF_TOKEN else "end of input"
        return ParseError(f"{message}, found {found!r}", token.offset)

    def span(self, start_token: Token) -> tuple[str, int]:
        """Return the collapsed source text and offset covering tokens since ``start_token``."""
        end = self.tokens[self.pos - 1]
        stop = end.offset + len(end.text)
        return collapse(self.src[start_token.offset : stop]), start_token.offset

    # -- expression grammar ----------------------------------------------

    def parse_expr(self) -> Expr:
        return self.parse_or()

    def parse_or(self) -> Expr:
        start = self.peek()
        node = self.parse_and()
        while self.accept_keyword("OR"):
            right = self.parse_and()
            text, offset = self.span(start)
            node = Logical(text, offset, "OR", node, right)
        return node

    def parse_and(self) -> Expr:
        start = self.peek()
        node = self.parse_not()
        while self.accept_keyword("AND"):
            right = self.parse_not()
            text, offset = self.span(start)
            node = Logical(text, offset, "AND", node, right)
        return node

    def parse_not(self) -> Expr:
        start = self.peek()
        if self.accept_keyword("NOT"):
            operand = self.parse_not()
            text, offset = self.span(start)
            return Not(text, offset, operand)
        return self.parse_predicate()

    def parse_predicate(self) -> Expr:
        start = self.peek()
        node = self.parse_additive()
        if self.at_op(*COMPARISON_OPS):
            op = str(self.next().value)
            right = self.parse_additive()
            text, offset = self.span(start)
            node = Compare(text, offset, op, node, right)
        elif self.accept_keyword("IS"):
            negated = self.accept_keyword("NOT") is not None
            self.expect_keyword("NULL")
            text, offset = self.span(start)
            node = IsNull(text, offset, node, negated)
        else:
            return node
        if self.at_op(*COMPARISON_OPS) or self.at_keyword("IS"):
            raise self.error("comparison operators are not associative")
        return node

    def parse_additive(self) -> Expr:
        start = self.peek()
        node = self.parse_multiplicative()
        while self.at_op("+", "-"):
            op = str(self.next().value)
            right = self.parse_multiplicative()
            text, offset = self.span(start)
            node = Binary(text, offset, op, node, right)
        return node

    def parse_multiplicative(self) -> Expr:
        start = self.peek()
        node = self.parse_unary()
        while self.at_op("*", "/", "%"):
            op = str(self.next().value)
            right = self.parse_unary()
            text, offset = self.span(start)
            node = Binary(text, offset, op, node, right)
        return node

    def parse_unary(self) -> Expr:
        start = self.peek()
        if self.accept_op("-"):
            operand = self.parse_unary()
            text, offset = self.span(start)
            return Unary(text, offset, "-", operand)
        return self.parse_primary()

    def parse_primary(self) -> Expr:
        start = self.peek()
        literal = self.parse_literal()
        if literal is not None:
            return literal
        if start.kind == IDENT_TOKEN:
            return self.parse_ident_expr()
        if self.accept_op("("):
            node = self.parse_expr()
            self.expect_op(")")
            return node
        raise self.error("expected an expression")

    def parse_literal(self) -> Expr | None:
        start = self.peek()
        if start.kind in (INT_TOKEN, FLOAT_TOKEN, TEXT_TOKEN):
            self.next()
            text, offset = self.span(start)
            return Literal(text, offset, start.value)
        if self.at_keyword("TRUE", "FALSE", "NULL"):
            self.next()
            value = {"TRUE": True, "FALSE": False, "NULL": None}[str(start.value)]
            text, offset = self.span(start)
            return Literal(text, offset, value)
        return None

    def parse_ident_expr(self) -> Expr:
        start = self.next()
        name = str(start.value)
        if self.at_op("("):
            return self.parse_call(start, name)
        if self.at_op(".") and self.peek(1).kind == IDENT_TOKEN:
            self.next()
            column = str(self.next().value)
            text, offset = self.span(start)
            return ColumnRef(text, offset, name, column)
        text, offset = self.span(start)
        return ColumnRef(text, offset, None, name)

    def parse_call(self, start: Token, name: str) -> Expr:
        self.expect_op("(")
        args: list[Expr] = self.parse_arg_list(name)
        self.expect_op(")")
        text, offset = self.span(start)
        node = FuncCall(text, offset, name, tuple(args))
        if name.lower() in AGGREGATE_NAMES:
            for arg in args:
                if contains_aggregate(arg):
                    raise ParseError(f"aggregate {name!r} may not be nested", offset)
        return node

    def parse_arg_list(self, name: str) -> list[Expr]:
        args: list[Expr] = []
        if self.at_op(")"):
            return args
        while True:
            star = self.peek()
            if star.kind == OP_TOKEN and star.value == "*":
                if name.lower() != "count":
                    raise self.error("'*' is only allowed as the argument of count")
                self.next()
                args.append(Star(collapse(self.src[star.offset : star.offset + 1]),
                                 star.offset, None))
            else:
                args.append(self.parse_expr())
            if not self.accept_op(","):
                return args

    # -- clause grammar ---------------------------------------------------

    def parse_query(self) -> Query:
        self.expect_keyword("SELECT")
        distinct = self.accept_keyword("DISTINCT") is not None
        select = self.parse_select_list()
        self.expect_keyword("FROM")
        from_table = str(self.expect_ident().value)
        join = self.parse_join()
        where = self.parse_where()
        group_by = self.parse_group_by()
        having = self.parse_having()
        order_by = self.parse_order_by()
        limit = self.parse_count_clause("LIMIT")
        offset = self.parse_count_clause("OFFSET")
        if self.peek().kind != EOF_TOKEN:
            raise self.error("unexpected trailing input")
        return Query(tuple(select), distinct, from_table, join, where,
                     tuple(group_by), having, tuple(order_by), limit, offset)

    def parse_select_list(self) -> list[SelectItem]:
        items: list[SelectItem] = [self.parse_select_item()]
        while self.accept_op(","):
            items.append(self.parse_select_item())
        return items

    def parse_select_item(self) -> SelectItem:
        start = self.peek()
        if self.at_op("*"):
            self.next()
            return SelectItem(Star("*", start.offset, None), None)
        if (start.kind == IDENT_TOKEN and self.peek(1).kind == OP_TOKEN
                and self.peek(1).value == "." and self.peek(2).kind == OP_TOKEN
                and self.peek(2).value == "*"):
            self.next()
            self.next()
            self.next()
            text, offset = self.span(start)
            return SelectItem(Star(text, offset, str(start.value)), None)
        expr = self.parse_expr()
        alias: str | None = None
        if self.accept_keyword("AS"):
            alias = str(self.expect_ident().value)
        return SelectItem(expr, alias)

    def parse_join(self) -> JoinClause | None:
        kind = "INNER"
        if self.accept_keyword("INNER"):
            self.expect_keyword("JOIN")
        elif self.accept_keyword("LEFT"):
            kind = "LEFT"
            self.expect_keyword("JOIN")
        elif self.accept_keyword("JOIN"):
            pass
        else:
            return None
        table = str(self.expect_ident().value)
        self.expect_keyword("ON")
        return JoinClause(kind, table, self.parse_expr())

    def parse_where(self) -> Expr | None:
        if self.accept_keyword("WHERE"):
            return self.parse_expr()
        return None

    def parse_group_by(self) -> list[Expr]:
        if not self.accept_keyword("GROUP"):
            return []
        self.expect_keyword("BY")
        items = [self.parse_expr()]
        while self.accept_op(","):
            items.append(self.parse_expr())
        return items

    def parse_having(self) -> Expr | None:
        if self.accept_keyword("HAVING"):
            return self.parse_expr()
        return None

    def parse_order_by(self) -> list[OrderItem]:
        if not self.accept_keyword("ORDER"):
            return []
        self.expect_keyword("BY")
        items: list[OrderItem] = []
        while True:
            expr = self.parse_expr()
            descending = False
            if self.accept_keyword("DESC"):
                descending = True
            else:
                self.accept_keyword("ASC")
            items.append(OrderItem(expr, descending))
            if not self.accept_op(","):
                return items

    def parse_count_clause(self, keyword: str) -> int | None:
        if not self.accept_keyword(keyword):
            return None
        token = self.peek()
        if token.kind != INT_TOKEN:
            raise self.error(f"{keyword} requires an integer")
        self.next()
        return int(token.value)  # type: ignore[arg-type]


def parse(src: str) -> Query:
    """Parse ``src`` into a :class:`Query`."""
    return _Parser(src).parse_query()

"""Expression evaluation: column resolution, scalar functions and operators."""

from __future__ import annotations

import dataclasses

from .errors import (
    AggregateError,
    AmbiguousColumnError,
    ArityError,
    TypeMismatchError,
    UnknownColumnError,
    UnknownFunctionError,
)
from .parser import (
    AGGREGATE_NAMES,
    Binary,
    ColumnRef,
    Compare,
    Expr,
    FuncCall,
    IsNull,
    Literal,
    Logical,
    Not,
    Star,
    Unary,
)
from .value import (
    and_,
    arith,
    compare_op,
    is_numeric,
    is_text,
    negate,
    not_,
    or_,
    type_of,
)


@dataclasses.dataclass(frozen=True)
class Binding:
    """One resolvable column of the working row."""

    table: str | None
    name: str


@dataclasses.dataclass
class Context:
    """Everything an expression may consult while it is evaluated."""

    bindings: list[Binding]
    row: list[object]
    tables: frozenset[str] = frozenset()
    aliases: dict[str, object] | None = None
    columns_visible: bool = True
    aggregates: dict[tuple[object, ...], object] | None = None


def expr_key(expr: Expr) -> tuple[object, ...]:
    """Return a structural key ignoring source text, used to match expressions."""
    if isinstance(expr, Literal):
        return ("lit", type_of(expr.value), expr.value)
    if isinstance(expr, ColumnRef):
        return ("col", expr.table, expr.name)
    if isinstance(expr, Star):
        return ("star", expr.table)
    if isinstance(expr, FuncCall):
        return ("func", expr.name.lower(), tuple(expr_key(a) for a in expr.args))
    if isinstance(expr, Unary):
        return ("unary", expr.op, expr_key(expr.operand))
    if isinstance(expr, Binary):
        return ("bin", expr.op, expr_key(expr.left), expr_key(expr.right))
    if isinstance(expr, Compare):
        return ("cmp", expr.op, expr_key(expr.left), expr_key(expr.right))
    if isinstance(expr, IsNull):
        return ("isnull", expr.negated, expr_key(expr.operand))
    if isinstance(expr, Not):
        return ("not", expr_key(expr.operand))
    if isinstance(expr, Logical):
        return ("logic", expr.op, expr_key(expr.left), expr_key(expr.right))
    raise TypeMismatchError(f"unsupported expression node {type(expr).__name__}")


def resolve_column(ctx: Context, table: str | None, name: str) -> object:
    """Look up a column reference in ``ctx``, honouring alias shadowing."""
    if table is None and ctx.aliases is not None and name in ctx.aliases:
        return ctx.aliases[name]
    if not ctx.columns_visible:
        raise UnknownColumnError(f"unknown output column {name!r}")
    if table is not None and table not in ctx.tables:
        raise UnknownTableErrorFor(table)
    matches = [
        index
        for index, binding in enumerate(ctx.bindings)
        if binding.name == name and (table is None or binding.table == table)
    ]
    if not matches:
        qualified = f"{table}.{name}" if table else name
        raise UnknownColumnError(f"unknown column {qualified!r}")
    if len(matches) > 1:
        raise AmbiguousColumnError(f"column {name!r} is ambiguous")
    return ctx.row[matches[0]]


def UnknownTableErrorFor(table: str) -> Exception:
    """Build the error raised for a qualified reference to an unknown table."""
    from .errors import UnknownTableError

    return UnknownTableError(f"unknown table {table!r}")


def evaluate(expr: Expr, ctx: Context) -> object:
    """Evaluate ``expr`` against ``ctx`` and return a microdb value."""
    if isinstance(expr, Literal):
        return expr.value
    if isinstance(expr, ColumnRef):
        return resolve_column(ctx, expr.table, expr.name)
    if isinstance(expr, FuncCall):
        return _eval_call(expr, ctx)
    if isinstance(expr, Unary):
        return negate(evaluate(expr.operand, ctx))
    if isinstance(expr, Binary):
        return arith(expr.op, evaluate(expr.left, ctx), evaluate(expr.right, ctx))
    if isinstance(expr, Compare):
        return compare_op(expr.op, evaluate(expr.left, ctx), evaluate(expr.right, ctx))
    if isinstance(expr, IsNull):
        result = evaluate(expr.operand, ctx) is None
        return (not result) if expr.negated else result
    if isinstance(expr, Not):
        return not_(as_logical(evaluate(expr.operand, ctx)))
    if isinstance(expr, Logical):
        return _eval_logical(expr, ctx)
    if isinstance(expr, Star):
        raise TypeMismatchError("'*' is not a value")
    raise TypeMismatchError(f"unsupported expression node {type(expr).__name__}")


def _eval_logical(expr: Logical, ctx: Context) -> bool | None:
    left = as_logical(evaluate(expr.left, ctx))
    right = as_logical(evaluate(expr.right, ctx))
    return and_(left, right) if expr.op == "AND" else or_(left, right)


def as_logical(v: object) -> bool | None:
    """Require a logical value; anything else is a type error."""
    if v is None or isinstance(v, bool):
        return v
    raise TypeMismatchError(f"expected a BOOL value, got {type_of(v)}")


def _eval_call(expr: FuncCall, ctx: Context) -> object:
    name = expr.name.lower()
    if name in AGGREGATE_NAMES:
        if ctx.aggregates is None:
            raise AggregateError(f"aggregate {expr.name!r} is not allowed here")
        key = expr_key(expr)
        if key not in ctx.aggregates:
            raise AggregateError(f"aggregate {expr.text!r} was not computed")
        return ctx.aggregates[key]
    if name not in SCALAR_ARITY:
        raise UnknownFunctionError(f"unknown function {expr.name!r}")
    args = [evaluate(arg, ctx) for arg in expr.args]
    _check_arity(name, len(args))
    return SCALAR_FUNCTIONS[name](args)


SCALAR_ARITY: dict[str, tuple[int, int | None]] = {
    "concat": (2, None),
    "upper": (1, 1),
    "lower": (1, 1),
    "length": (1, 1),
    "abs": (1, 1),
    "coalesce": (1, None),
}


def _check_arity(name: str, count: int) -> None:
    low, high = SCALAR_ARITY[name]
    if count < low or (high is not None and count > high):
        want = str(low) if high == low else f"at least {low}"
        raise ArityError(f"function {name!r} expects {want} arguments, got {count}")


def _require_text(name: str, v: object) -> None:
    if not is_text(v):
        raise TypeMismatchError(f"function {name!r} requires TEXT, got {type_of(v)}")


def _fn_concat(args: list[object]) -> object:
    for arg in args:
        if arg is not None:
            _require_text("concat", arg)
    if any(arg is None for arg in args):
        return None
    return "".join(str(arg) for arg in args)


def _fn_upper(args: list[object]) -> object:
    if args[0] is None:
        return None
    _require_text("upper", args[0])
    return str(args[0]).upper()


def _fn_lower(args: list[object]) -> object:
    if args[0] is None:
        return None
    _require_text("lower", args[0])
    return str(args[0]).lower()


def _fn_length(args: list[object]) -> object:
    if args[0] is None:
        return None
    _require_text("length", args[0])
    return len(str(args[0]))


def _fn_abs(args: list[object]) -> object:
    if args[0] is None:
        return None
    if not is_numeric(args[0]):
        raise TypeMismatchError(f"function 'abs' requires a number, got {type_of(args[0])}")
    return abs(args[0])  # type: ignore[arg-type]


def _fn_coalesce(args: list[object]) -> object:
    for arg in args:
        if arg is not None:
            return arg
    return None


SCALAR_FUNCTIONS: dict[str, object] = {
    "concat": _fn_concat,
    "upper": _fn_upper,
    "lower": _fn_lower,
    "length": _fn_length,
    "abs": _fn_abs,
    "coalesce": _fn_coalesce,
}

